const months={Januari:'January',Februari:'February',Mac:'March',April:'April',Mei:'May',Jun:'June',Julai:'July',Ogos:'August',September:'September',Oktober:'October',November:'November',Disember:'December',Jan:'Jan',Feb:'Feb',Apr:'Apr',Jul:'Jul',Ogo:'Aug',Sep:'Sep',Okt:'Oct',Nov:'Nov',Dis:'Dec'};
export function translateUI(source,language='ms'){
  if(language!=='en'||typeof source!=='string')return source;
  const trimmed=source.trim().replace(/\s+/g,' ');
  const exact=translations[trimmed];
  if(exact)return source.replace(source.trim(),exact);
  // These tails may contain customer names, references or provider names.
  for(const [prefix,english] of [['Jumlah dibayar: ','Paid total: '],['Jumlah bil: ','Bill total: '],['Caj penghantaran dalam pesanan: ','Shipping included in order: '],['Urus ','Manage '],['Logo ','Logo for '],['Gambar cover ','Cover image for '],['Rujukan: ','Reference: '],['Sumber: ','Source: ']])if(trimmed.startsWith(prefix))return english+trimmed.slice(prefix.length);
  if(/^(Bayaran disahkan|Menunggu semakan bayaran|Permohonan ditolak) · /.test(trimmed)){
    const split=trimmed.indexOf(' · ');return (translations[trimmed.slice(0,split)]||trimmed.slice(0,split))+trimmed.slice(split);
  }
  if(/^\d+ halaman dimuatkan(?: · \d+ padanan)?\.$/.test(trimmed))return trimmed.replace(/^(\d+) halaman dimuatkan/,(_,n)=>n+(n==='1'?' page loaded':' pages loaded')).replace(' padanan',' matches');
  if(/^Harga borong RM15\/unit digunakan untuk semua \d+ sticker\.$/.test(trimmed))return trimmed.replace(/^Harga borong RM15\/unit digunakan untuk semua (\d+) sticker\.$/,'Bulk pricing of RM15/unit applies to all $1 stickers.');
  if(/[↗*]$/.test(trimmed)){const base=trimmed.slice(0,-1).trim();if(translations[base])return translations[base]+' '+trimmed.slice(-1);}
  if(/^Pilih pautan [A-Za-z]+ yang betul$/.test(trimmed))return trimmed.replace(/^Pilih pautan (.+) yang betul$/,'Choose the correct $1 link');
  const date=text=>text.replace(/\b(Januari|Februari|Mac|Mei|Jun|Julai|Ogos|Oktober|Disember|Ogo|Okt|Dis)\b/g,word=>months[word]||word);
  if(/^Halaman tahunan · tamat /.test(trimmed))return 'Annual page · expires '+date(trimmed.slice('Halaman tahunan · tamat '.length));
  if(/^Dikemas kini: /.test(trimmed))return 'Updated: '+date(trimmed.slice('Dikemas kini: '.length));
  if(/^Jumlah produk: RM[\s\d.,]+$/.test(trimmed))return trimmed.replace('Jumlah produk:','Product total:');
  const parts=trimmed.split(' · ');
  const result=parts.map(part=>{
    if(part.includes('@'))return part;
    if(translations[part])return translations[part];
    for(const [prefix,en] of [['Dicipta ','Created '],['Dikemas kini ','Updated ']])if(part.startsWith(prefix)&&/^\d/.test(part.slice(prefix.length)))return en+date(part.slice(prefix.length));
    if(/^RM[\s\d.,]+(?: \/ \d+ bulan| tahun pertama| setahun)?$/.test(part))return part.replace('bulan','months').replace('tahun pertama','first year').replace('setahun','/year').replace('RM30 /year','RM30/year');
    const line=part.match(/^(.*?)((?: × \d+)(?: [—·] RM[\s\d.,]+)?)$/);
    if(line&&translations[line[1]])return translations[line[1]]+line[2];
    return part;
  }).join(' · ');
  return result===trimmed?source:result;
}
